                    dvc_infos[dvc_fs.name(info["name"])] = info
        dvc_exists = bool(dvc_infos) or dvc_fs.exists(dvc_path)
    else:
        dvc_exists = False

    fs_exists = False
    fs_infos = {}
    ignore_subrepos = kwargs.get("ignore_subrepos", True)
    if not dvc_only:
        fs = self.repo.fs
        fs_path = self._from_key(key)
        try:
            fs_info = fs.info(fs_path)
            if fs_info["type"] == "file":
                fs_infos[""] = fs_info
            else:
                for info in repo.dvcignore.ls(
                    fs, fs_path, detail=True, ignore_subrepos=ignore_subrepos
                ):
                    fs_infos[fs.name(info["name"])] = info
            fs_exists = bool(fs_infos) or fs.exists(fs_path)
        except (FileNotFoundError, NotADirectoryError):
            pass

    dvcfiles = kwargs.get("dvcfiles", False)

    infos = []
    paths = []
    names = set(dvc_infos.keys()) | set(fs_infos.keys())

    # If neither DVC nor filesystem found anything, and the path doesn't exist
    # in either DVC or the filesystem, raise FileNotFoundError
    if not names and not dvc_exists and not fs_exists:
        raise FileNotFoundError(errno.ENOENT, os.strerror(errno.ENOENT), path)

    # Special case: If we have a DVC-tracked file but it's a directory on the filesystem,
    # we should only return the directory contents, not the file itself
    is_dvc_file_fs_dir = (
        "" in dvc_infos 
        and dvc_infos[""]["type"] == "file" 
        and fs_exists 
        and fs_info["type"] == "directory"
    )

    for name in names:
        if not dvcfiles and _is_dvc_file(name):
            continue

        # Skip the empty name (which represents the directory/file itself) if it's a DVC file
        # but a directory on the filesystem - we only want to return the directory contents
        if name == "" and is_dvc_file_fs_dir:
            continue

        entry_path = self.join(path, name) if name else path
        info = _merge_info(
            repo, (*subkey, name), fs_infos.get(name), dvc_infos.get(name)
        )
        info["name"] = entry_path
        infos.append(info)
        paths.append(entry_path)
